#include "stdafx.h"#include "H_Class.h"#include "../ScriptoH/Trans.h"#include <SR_DCU.h>using namespace std;using namespace ns_translator;static SBlockCreate AUXCALC( "AUXCALC", SH_AUXCALC::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_AUXCALC,W_AUXCALC,275)void SH_AUXCALC::InitParm(){#include "Blocks/AUXCALC.h" s_defFlag = SVarInfo::efParam;#include "Blocks/AUXCALC_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}void SH_AUXCALC::OnReadProject( KBmBase *pRoot, KBmBase *pModule ){  ASS( _countof(W->EXPR)==_countof(m_Code) )  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  __super::CreateCodes( pRoot, pModule, m_Code, pp, _countof(W->EXPR) );}void SH_AUXCALC::SaveBlock( HANDLE hFile ){  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  __super::SaveBlock( hFile, m_Code, pp, _countof(pp) );}bool SH_AUXCALC::RestoreBlock( HANDLE hFile ){  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  return __super::RestoreBlock( hFile, m_Code, pp, _countof(pp) );}void SH_AUXCALC::StepBeforeRestoreState( LPCSTR pSystemName, KBmBase *pRoot, KBmBase *pModule ){  bErrorInitialization = false;  for( int n=0; n<_countof(m_Code); ++n )  {    for( int i=0; i<m_Code[n].cVars; i++ )    {      KCalcVar &cv = ((KCalcVar*)m_Code[n].pVars)[i];      bool r = cv.Init( pRoot );      if( !r )      {        OutputDebugString( " (" );        OutputDebugString( BlockName );        OutputDebugString( ")\n" );        bErrorInitialization = true;#ifndef _DEBUG        break;#endif      }    }  }}void SH_AUXCALC::GetParams( KHBridge2SysParam &params ){  for( int i=0;i<_countof(W->РасчетC); ++i )  {    char name[24] = { 0 };    sprintf_s( name, "РасчетC_%d", i);    Add2Params( W->РасчетC[i].V, name, params );  }}void SH_AUXCALC::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  if( bErrorInitialization )  {    for( int n=0; n<_countof(m_Code); ++n )    {      W->EXECSTS[n] = W->_EXECSTS::Fail;      W->CSTS[n] = W->_CSTS::BAD;    }    W->PVSTS = W->_PVSTS::Bad;    return;  }  for( int n=0; n<_countof(m_Code); ++n )  {    switch( W->РасчетC[n].V )    {    case W->_РасчетC::Брать_с_P6:    case W->_РасчетC::Брать_с_P5:    case W->_РасчетC::Брать_с_P4:    case W->_РасчетC::Брать_с_P3:    case W->_РасчетC::Брать_с_P2:    case W->_РасчетC::Брать_с_P1:    case W->_РасчетC::Брать_с_P0:      W->C[n] = W->P[ W->РасчетC[n].V - W->_РасчетC::Брать_с_P0 ];      W->EXECSTS[n] = W->_EXECSTS::Ok;      W->CSTS[n] = W->_CSTS::NORMAL;      break;    default:    case W->_РасчетC::Честно:      if( Calc( m_Code[n], W->C[n] ) )      {        W->EXECSTS[n] = W->_EXECSTS::Ok;        W->CSTS[n] = W->_CSTS::NORMAL;      }      else      {        W->EXECSTS[n] = W->_EXECSTS::Fail;        W->CSTS[n] = W->_CSTS::BAD;      }      break;    }  }  if( W->PVSRC.V >= W->_PVSRC::C1 && W->PVSRC.V <= W->_PVSRC::C8 )  {    int n = W->PVSRC.V - W->_PVSRC::C1 + 1;    W->PV = W->C[n];  }  else if( W->PVSRC.V >= W->_PVSRC::P1 && W->PVSRC.V <= W->_PVSRC::P6 )  {    int n = W->PVSRC.V - W->_PVSRC::P1 + 1;    W->PV = W->P[n];  }  else  {    ASSD(0);  }  if( W->PVSTSSRC.V >= W->_PVSTSSRC::C1 && W->PVSTSSRC.V <= W->_PVSTSSRC::C8 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::C1 + 1;    W->PVSTS.V = W->CSTS[n].V;  }  else if( W->PVSTSSRC.V >= W->_PVSTSSRC::PSTS1 && W->PVSTSSRC.V <= W->_PVSTSSRC::PSTS6 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::PSTS1 + 1;    W->PVSTS.V = W->PSTS[n].V;  }  else if( W->PVSTSSRC.V >= W->_PVSTSSRC::CSTS1 && W->PVSTSSRC.V <= W->_PVSTSSRC::CSTS8 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::CSTS1 + 1;    W->PVSTS.V = W->CSTS[n].V;  }  else if( W->PVSTSSRC.V >= W->_PVSTSSRC::P1 && W->PVSTSSRC.V <= W->_PVSTSSRC::P6 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::P1 + 1;    if( IsNaN( W->P[n]) )      W->PVSTS.V = W->PVSTS.Bad;    else      W->PVSTS.V = W->PVSTS.Normal;  }  else  {    ASSD(0);  }  OutputConnectionsTransfer();}void SH_AUXCALC::StepAfterRestoreState(){  W->HIALM.V = W->HIALM.NoAlarm;}